    try:
        with open(p,'r',encoding='utf-8') as f:
            for line in f:
                line=line.strip()
                if not line:
                    continue
                try:
                    obj=json.loads(line)
                except:
                    continue
                ts=(obj.get('timestamp') or obj.get('createdAt') or '')
                if '2026-05-04' not in ts:
                    continue
                usage=((obj.get('message') or {}).get('usage') or obj.get('usage') or {})
                total=usage.get('total') or usage.get('totalTokens') or 0
                inp=usage.get('input') or usage.get('inputTokens') or 0
                out=usage.get('output') or usage.get('outputTokens') or 0
                cr=usage.get('cacheRead') or usage.get('cache_read_input_tokens') or 0
                cw=usage.get('cacheWrite') or usage.get('cache_creation_input_tokens') or 0
                if not any([total,inp,out,cr,cw]):
                    continue
                meta=obj.get('meta') or {}
                model=meta.get('model') or obj.get('model') or 'unknown'
                rows.append((os.path.basename(p), model, total or (inp+out+cr+cw), inp, out, cr, cw, ts))
    except Exception:
