import json, glob, os
from collections import defaultdict
base=os.path.expanduser('~/.openclaw/agents/main/sessions')
dates={'2026-05-01','2026-05-02','2026-05-03'}
info={}
for p in glob.glob(base+'/*.jsonl'):
    sid=os.path.basename(p).replace('.jsonl','')
    try:
        with open(p,'r',encoding='utf-8') as f:
            text=''
            first=None
            total=0
            for line in f:
                if not first:
                    first=line[:500]
                try: obj=json.loads(line)
                except: continue
                ts=(obj.get('timestamp') or obj.get('createdAt') or '')
                if not any(d in ts for d in dates):
                    continue
                usage=((obj.get('message') or {}).get('usage') or obj.get('usage') or {})
                inp=usage.get('input') or usage.get('inputTokens') or 0
                out=usage.get('output') or usage.get('outputTokens') or 0
                cr=usage.get('cacheRead') or usage.get('cache_read_input_tokens') or 0
                total += int(inp)+int(out)+int(cr)
                if not text:
                    msg=(obj.get('message') or {}).get('content') or obj.get('content') or ''
                    if isinstance(msg,list):
                        msg=' '.join(str(x) for x in msg)
                    text=str(msg)[:300]
            if total>0:
                info[sid]=(total,text,first)
    except: pass
for sid,(total,text,first) in sorted(info.items(), key=lambda kv: kv[1][0], reverse=True)[:20]:
    print('SID',sid,'TOTAL',total)
    print('TEXT',text.replace('\n',' ')[:220])
    print('FIRST',first[:220].replace('\n',' '))
    print('---')
