import os, glob, json, re
cands=[]
for root in [os.path.expanduser('~/.openclaw'), '/Users/mac/.openclaw/workspace']:
    for p in glob.glob(root+'/**/*', recursive=True):
        if os.path.isfile(p) and any(p.endswith(ext) for ext in ['.json','.jsonc','.yaml','.yml','.md','.sh','.toml']):
            cands.append(p)
patterns=['hourly backup','每日新闻推送','早间学习推送','午后学习推送','晚间学习推送','heartbeat','HeartBeat','HEARTBEAT','openclaw.json hourly backup','每日凌晨1点备份']
for p in sorted(set(cands)):
    try:
        txt=open(p,'r',encoding='utf-8',errors='ignore').read()
    except:
        continue
    hits=[pat for pat in patterns if pat in txt]
    if hits:
        print('\nFILE',p)
        print('HITS',hits)
        for pat in hits[:3]:
            idx=txt.find(pat)
            s=max(0,idx-180); e=min(len(txt),idx+320)
            print('--- snippet for',pat,'---')
            print(txt[s:e].replace('\r',' '))
